<?php
session_start();
require '../../config/db.php';
if (!isset($_SESSION['admin_id'])) { header('Location: ../../auth/login-admin.php'); exit; }
function h($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function badgeStatus($s){ $c='st-'.str_replace([' ','í'],['-','i'],strtolower((string)$s)); return '<span class="hd-badge '.h($c).'">'.h(ucfirst((string)$s)).'</span>'; }
function badgePrioridade($p){ $p=$p?:'media'; return '<span class="hd-badge pr-'.h($p).'">'.h(ucfirst($p)).'</span>'; }
if (isset($_POST['excluir_solicitacao'])) { $id=(int)($_POST['solicitacao_id']??0); if($id>0){$pdo->prepare('DELETE FROM solicitacoes WHERE id=?')->execute([$id]); $_SESSION['success_msg']='Chamado excluído com sucesso.';} header('Location: dashboard.php'); exit; }
$pagina=max(1,(int)($_GET['pagina']??1));$limite=10;$offset=($pagina-1)*$limite;$status=trim($_GET['status']??'');$prioridade=trim($_GET['prioridade']??'');$busca=trim($_GET['q']??'');
$where=[];$params=[];if($status!==''){$where[]='s.status=?';$params[]=$status;}if($prioridade!==''){$where[]='s.prioridade=?';$params[]=$prioridade;}if($busca!==''){$where[]='(s.protocolo LIKE ? OR s.titulo LIKE ? OR s.descricao LIKE ? OR c.nome LIKE ? OR c.email LIKE ?)';$like='%'.$busca.'%';array_push($params,$like,$like,$like,$like,$like);} $whereSql=$where?'WHERE '.implode(' AND ',$where):'';
$stmt=$pdo->prepare("SELECT COUNT(*) FROM solicitacoes s JOIN clientes c ON c.id=s.cliente_id $whereSql");$stmt->execute($params);$total=(int)$stmt->fetchColumn();$totalPaginas=max(1,(int)ceil($total/$limite));
$sql="SELECT s.*,c.nome cliente_nome,c.email cliente_email,c.telefone cliente_telefone,c.logo cliente_logo FROM solicitacoes s JOIN clientes c ON c.id=s.cliente_id $whereSql ORDER BY FIELD(s.prioridade,'urgente','alta','media','baixa'), FIELD(s.status,'pendente','em andamento','nao resolvido','cancelado','finalizado'), s.data DESC LIMIT $limite OFFSET $offset";$stmt=$pdo->prepare($sql);$stmt->execute($params);$solicitacoes=$stmt->fetchAll(PDO::FETCH_ASSOC);
$kpis=['total'=>(int)$pdo->query('SELECT COUNT(*) FROM solicitacoes')->fetchColumn(),'pendente'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='pendente'")->fetchColumn(),'andamento'=>(int)$pdo->query("SELECT COUNT(*) FROM solicitacoes WHERE status='em andamento'")->fetchColumn(),'clientes'=>(int)$pdo->query('SELECT COUNT(*) FROM clientes')->fetchColumn()];
$clientes=$pdo->query('SELECT id,nome,email,telefone,logo FROM clientes ORDER BY nome ASC LIMIT 8')->fetchAll(PDO::FETCH_ASSOC);
$success=$_SESSION['success_msg']??'';$error=$_SESSION['error_msg']??'';unset($_SESSION['success_msg'],$_SESSION['error_msg']);
?>
