<section class="hd-kpis"><div class="hd-kpi"><span>Total de chamados</span><strong><?= $kpis['total'] ?></strong><small>Histórico geral</small></div><div class="hd-kpi"><span>Pendentes</span><strong><?= $kpis['pendente'] ?></strong><small>Aguardando triagem</small></div><div class="hd-kpi"><span>Em atendimento</span><strong><?= $kpis['andamento'] ?></strong><small>Fila ativa</small></div><div class="hd-kpi"><span>Clientes</span><strong><?= $kpis['clientes'] ?></strong><small>Empresas cadastradas</small></div></section>
<div class="hd-grid"><section class="hd-card hd-card-pad"><div class="hd-section-head"><div><h2>Fila inteligente de chamados</h2><p>Use filtros, gerencie status, valor e observação em cada chamado.</p></div><button class="hd-btn hd-btn-outline" onclick="imprimirRelatorio()">🖨️ Imprimir</button></div><form method="GET" class="hd-form-grid" style="margin-bottom:16px"><div class="hd-field"><label class="hd-label">Buscar</label><input class="hd-input" name="q" value="<?= h($busca) ?>" placeholder="Protocolo, cliente, email ou descrição"></div><div class="hd-field"><label class="hd-label">Status</label><select class="hd-select" name="status"><option value="">Todos</option><?php foreach(['pendente','em andamento','finalizado','nao resolvido','cancelado'] as $st): ?><option value="<?= h($st) ?>" <?= $status===$st?'selected':'' ?>><?= h(ucfirst($st)) ?></option><?php endforeach; ?></select></div><div class="hd-field"><label class="hd-label">Prioridade</label><select class="hd-select" name="prioridade"><option value="">Todas</option><?php foreach(['urgente','alta','media','baixa'] as $pr): ?><option value="<?= h($pr) ?>" <?= $prioridade===$pr?'selected':'' ?>><?= h(ucfirst($pr)) ?></option><?php endforeach; ?></select></div><div class="hd-field"><label class="hd-label">Ação</label><button class="hd-btn hd-btn-primary" type="submit">🔎 Filtrar fila</button></div></form>
<div class="hd-table-wrap"><table class="hd-table"><thead><tr><th>Chamado</th><th>Cliente</th><th>Status</th><th>Prioridade</th><th>Valor</th><th>Ações</th></tr></thead><tbody><?php if(!$solicitacoes): ?><tr><td colspan="6"><div class="hd-empty">📭<strong>Nenhum chamado encontrado</strong>Altere os filtros ou aguarde novas solicitações.</div></td></tr><?php endif; ?><?php foreach($solicitacoes as $s): ?><tr><td><div class="hd-ticket-title"><?= h($s['titulo'] ?: mb_substr($s['descricao'],0,90)) ?></div><div class="hd-ticket-meta"><?= h($s['protocolo'] ?: '#'.$s['id']) ?> • <?= date('d/m/Y H:i', strtotime($s['data'])) ?></div><div class="hd-ticket-meta"><?= h($s['categoria'] ?: 'Suporte técnico') ?><?= !empty($s['equipamento'])?' • '.h($s['equipamento']):'' ?></div></td><td><div class="hd-client-card"><div class="hd-client-avatar"><?php if(!empty($s['cliente_logo'])): ?><img src="../../uploads/clientes/logos/<?= h(basename($s['cliente_logo'])) ?>" alt="Logo"><?php else: ?><?= h(mb_strtoupper(mb_substr($s['cliente_nome'],0,1))) ?><?php endif; ?></div><div><strong><?= h($s['cliente_nome']) ?></strong><br><span class="hd-ticket-meta"><?= h($s['cliente_telefone'] ?: $s['cliente_email']) ?></span></div></div></td><td><?= badgeStatus($s['status']) ?></td><td><?= badgePrioridade($s['prioridade']??'media') ?></td><td><strong>R$ <?= number_format((float)($s['preco']??0),2,',','.') ?></strong></td><td><details><summary class="hd-btn hd-btn-outline">Gerenciar</summary><div style="min-width:280px;margin-top:10px;display:grid;gap:10px"><form method="POST" action="../../controllers/atualizar-status.php" class="hd-field"><input type="hidden" name="solicitacao_id" value="<?= (int)$s['id'] ?>"><select class="hd-select" name="novo_status"><?php foreach(['pendente','em andamento','finalizado','nao resolvido','cancelado'] as $st): ?><option value="<?= h($st) ?>" <?= $s['status']===$st?'selected':'' ?>><?= h(ucfirst($st)) ?></option><?php endforeach; ?></select><button class="hd-btn hd-btn-primary" type="submit">Atualizar status</button></form><form method="POST" action="../../controllers/definir-preco.php" class="hd-field"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><input class="hd-input" name="preco" value="<?= h(number_format((float)($s['preco']??0),2,',','.')) ?>" placeholder="Valor"><button class="hd-btn hd-btn-light" type="submit">Salvar valor</button></form><form method="POST" action="../../controllers/atualizar-observacao.php" class="hd-field"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><textarea class="hd-textarea" name="observacao" placeholder="Observação técnica"><?= h($s['observacao']??'') ?></textarea><button class="hd-btn hd-btn-light" type="submit">Salvar observação</button></form><a class="hd-btn hd-btn-success" href="itens-chamado.php?id=<?= (int)$s['id'] ?>">Produtos/serviços</a><form method="POST" onsubmit="return confirm('Excluir este chamado?')"><input type="hidden" name="solicitacao_id" value="<?= (int)$s['id'] ?>"><button class="hd-btn hd-btn-danger" name="excluir_solicitacao" type="submit">Excluir chamado</button></form></div></details></td></tr><?php endforeach; ?></tbody></table></div><?php if($totalPaginas>1): ?><div class="hd-pagination"><?php for($i=1;$i<=$totalPaginas;$i++): ?><a class="<?= $i===$pagina?'active':'' ?>" href="?pagina=<?= $i ?>&status=<?= urlencode($status) ?>&prioridade=<?= urlencode($prioridade) ?>&q=<?= urlencode($busca) ?>"><?= $i ?></a><?php endfor; ?></div><?php endif; ?></section>
<aside class="hd-sidebar"><section class="hd-card hd-card-pad"><div class="hd-section-head"><h3>Clientes recentes</h3></div><div class="hd-sidebar-list"><?php foreach($clientes as $c): ?><div class="hd-mini"><div class="hd-client-card"><div class="hd-client-avatar"><?php if(!empty($c['logo'])): ?><img src="../../uploads/clientes/logos/<?= h(basename($c['logo'])) ?>" alt="Logo"><?php else: ?><?= h(mb_strtoupper(mb_substr($c['nome'],0,1))) ?><?php endif; ?></div><div><strong><?= h($c['nome']) ?></strong><p><?= h($c['telefone'] ?: $c['email']) ?></p></div></div><div class="hd-actions" style="margin-top:10px"><a class="hd-btn hd-btn-outline" href="editar-cliente.php?id=<?= (int)$c['id'] ?>">Editar</a><a class="hd-btn hd-btn-light" href="solicitacoes.php?id=<?= (int)$c['id'] ?>">Chamados</a></div></div><?php endforeach; ?></div><a class="hd-btn hd-btn-primary" style="margin-top:14px;width:100%" href="cadastrar-cliente.php">➕ Novo cliente</a></section></aside></div></div></main></div><script>window.HD_CHAT_CONFIG={endpointBase:'../../controllers/',chatUrl:'mensagens.php'};</script><script src="../../assets/js/live-chat-alerts.js"></script><script src="../../assets/js/helpdesk-pro.js"></script></body></html>